#!/bin/bash
# ==============================================================================
# Smart Parking Self-Contained Automated Deployment Script
# Supports: Node-RED installation, context storage setup, security configuration,
# path mapping adjustments, and clean databases. All code is embedded.
# ==============================================================================

# Ensure script is run as root
if [ "$EUID" -ne 0 ]; then
  echo -e "\e[31mError: Please run this script with sudo (e.g., sudo ./deploy.sh)\e[0m"
  exit 1
fi

echo -e "\e[32m==================================================\e[0m"
echo -e "\e[32mStarting Smart Parking Self-Contained Auto-Deploy...\e[0m"
echo -e "\e[32m==================================================\e[0m"

# 1. Ask for Target Linux Username
DEFAULT_USER="$SUDO_USER"
if [ -z "$DEFAULT_USER" ] || [ "$DEFAULT_USER" = "root" ]; then
    DEFAULT_USER="smartev"
fi

read -p "Enter the target Linux system username [$DEFAULT_USER]: " TARGET_USER
TARGET_USER=${TARGET_USER:-$DEFAULT_USER}

if ! id "$TARGET_USER" &>/dev/null; then
    echo -e "\e[31mError: User '$TARGET_USER' does not exist on this system. Please create the user first.\e[0m"
    exit 1
fi

USER_HOME=$(eval echo "~$TARGET_USER")
ND_DIR="$USER_HOME/.node-red"

# 2. Ask for Node-RED Credentials
read -p "Enter desired Node-RED Admin Username [admin]: " NR_ADMIN
NR_ADMIN=${NR_ADMIN:-admin}

while true; do
    read -s -p "Enter Node-RED Admin Password: " NR_PASS1
    echo
    read -s -p "Confirm Node-RED Admin Password: " NR_PASS2
    echo
    if [ "$NR_PASS1" = "$NR_PASS2" ]; then
        if [ -z "$NR_PASS1" ]; then
            echo -e "\e[31mPassword cannot be empty!\e[0m"
        else
            break
        fi
    else
        echo -e "\e[31mPasswords do not match. Please try again.\e[0m"
    fi
done

# 3. Install System Dependencies
echo -e "\n\e[34m[1/7] Installing System Packages (Node.js, Mosquitto, Pip)...\e[0m"
apt update
apt install -y curl nodejs npm mosquitto mosquitto-clients python3-pip python3-pymodbus

# Install pymodbus via pip just in case python3-pymodbus is not available
python3 -c "import pymodbus" &>/dev/null
if [ $? -ne 0 ]; then
    pip3 install pymodbus
fi

# 4. Install Node-RED (if not already installed)
echo -e "\n\e[34m[2/7] Checking Node-RED installation...\e[0m"
if ! command -v node-red &>/dev/null; then
    echo "Node-RED not found. Running official installation script..."
    # Running official unattended installer for Node-RED on Raspberry Pi / Debian
    curl -sL https://raw.githubusercontent.com/node-red/linux-installers/master/deb/update-nodejs-and-nodered | bash -s -- --yes --unattended
else
    echo "Node-RED is already installed."
fi

# Stop Node-RED service before configuring files
echo "Stopping Node-RED service..."
systemctl stop nodered &>/dev/null
systemctl stop node-red &>/dev/null

# 5. Create Node-RED settings and install Dashboard packages
echo -e "\n\e[34m[3/7] Setting up Node-RED user directory & modules...\e[0m"
mkdir -p "$ND_DIR"

# Copy default settings.js if not exists
if [ ! -f "$ND_DIR/settings.js" ]; then
    echo "Creating default settings.js..."
    if [ -f /usr/lib/node_modules/node-red/settings.js ]; then
        cp /usr/lib/node_modules/node-red/settings.js "$ND_DIR/settings.js"
    elif [ -f /usr/local/lib/node_modules/node-red/settings.js ]; then
        cp /usr/local/lib/node_modules/node-red/settings.js "$ND_DIR/settings.js"
    else
        # Start and kill node-red to let it initialize settings
        timeout 5s node-red &>/dev/null
    fi
fi

# Install required NPM modules inside the user directory
cd "$ND_DIR"
echo "Installing Node-RED contrib packages (Dashboard, Modbus, InfluxDB)..."
npm install --no-audit --no-fund bcryptjs node-red-dashboard@3.6.6 node-red-contrib-modbus@5.45.2 node-red-contrib-influxdb@0.7.0

# 6. Generate Password Hash and configure settings.js
echo -e "\n\e[34m[4/7] Securing Node-RED UI editor & Context Storage...\e[0m"
HASH_CMD="const bcrypt = require('bcryptjs'); console.log(bcrypt.hashSync('$NR_PASS1', 8));"
NR_HASH=$(node -e "$HASH_CMD" 2>/dev/null)

if [ -z "$NR_HASH" ] || [ "$NR_HASH" = "error" ]; then
    echo "Warning: Direct bcryptjs hash failed. Attempting fallback via node-red-admin..."
    NR_HASH=$(npx node-red-admin hash-pw "$NR_PASS1" 2>/dev/null | tail -n 1)
fi

if [ -z "$NR_HASH" ]; then
    echo -e "\e[31mError: Could not generate bcrypt hash. Node-RED credentials cannot be set automatically.\e[0m"
    exit 1
fi

# Write a temporary python script to do settings.js patching
cat << 'EOF' > update_settings.py
import sys, re

settings_path = sys.argv[1]
username = sys.argv[2]
password_hash = sys.argv[3]

with open(settings_path, 'r', encoding='utf-8') as f:
    content = f.read()

# Make sure flowFile: 'flows.json' is uncommented and set
content = re.sub(r'//\s*flowFile:\s*'flows.json',', "flowFile: 'flows.json',", content)

# Check if flowFile is already present, if not add it
if 'flowFile:' not in content:
    content = content.replace('module.exports = {', "module.exports = {
    flowFile: 'flows.json',")

# Build adminAuth block
admin_auth_block = "adminAuth: {
    type: "credentials",
    users: [{
        username: "" + username + "",
        password: "" + password_hash + "",
        permissions: "*"
    }]
},"

# Replace existing adminAuth block (either commented or active)
commented_auth_pattern = r'//\s*adminAuth:\s*\{.*?//\s*\},?'
active_auth_pattern = r'adminAuth:\s*\{.*?\},?'

if re.search(active_auth_pattern, content, re.DOTALL):
    content = re.sub(active_auth_pattern, admin_auth_block, content, 1, re.DOTALL)
elif re.search(commented_auth_pattern, content, re.DOTALL):
    content = re.sub(commented_auth_pattern, admin_auth_block, content, 1, re.DOTALL)
else:
    content = content.replace('module.exports = {', "module.exports = {
    " + admin_auth_block)

# Enable contextStorage: default -> localfilesystem
context_storage_block = "contextStorage: {
    default: {
        module: "localfilesystem"
    }
},"

# Pattern to match the commented contextStorage default block in settings.js
commented_cs_pattern = r'//\s*contextStorage:\s*\{.*?//\s*default:\s*\{.*?//\s*module:\s*["']localfilesystem["'].*?//\s*\},?\s*//\s*\},?'
active_cs_pattern = r'contextStorage:\s*\{.*?default:\s*\{.*?module:\s*["']localfilesystem["'].*?\},?\s*\},?'

if re.search(active_cs_pattern, content, re.DOTALL):
    content = re.sub(active_cs_pattern, context_storage_block, content, 1, re.DOTALL)
elif re.search(commented_cs_pattern, content, re.DOTALL):
    content = re.sub(commented_cs_pattern, context_storage_block, content, 1, re.DOTALL)
else:
    content = content.replace('module.exports = {', "module.exports = {
    " + context_storage_block)

with open(settings_path, 'w', encoding='utf-8') as f:
    f.write(content)
print('Successfully configured settings.js credentials and contextStorage!')
EOF

python3 update_settings.py "$ND_DIR/settings.js" "$NR_ADMIN" "$NR_HASH"
rm update_settings.py

# 7. Unpack Project Files (Decoded from Base64) & Dynamic Path Adjustments
echo -e "\n\e[34m[5/7] Decoding and deploying scripts and config files...\e[0m"

# Decode python daemon scripts
echo "" | base64 -d > "$USER_HOME/rfid.py"
echo "" | base64 -d > "$USER_HOME/rfid1.py" # maintain compatibility with both names
echo "" | base64 -d > "$USER_HOME/chargers_poller.py"
chmod +x "$USER_HOME/rfid.py" "$USER_HOME/rfid1.py" "$USER_HOME/chargers_poller.py"

# Decode config files
echo "" | base64 -d > "$ND_DIR/smart-parking-config.json"

# Decode flow files
echo "" | base64 -d > "$ND_DIR/flows.json"
echo "Adjusting paths in flows.json to match target user..."
sed -i "s|/home/smartev/|/home/$TARGET_USER/|g" "$ND_DIR/flows.json"
sed -i "s|/home/lefteris/|/home/$TARGET_USER/|g" "$ND_DIR/flows.json"
sed -i "s|rfid1.py|rfid.py|g" "$ND_DIR/flows.json"

# 8. Initialize clean state (excluding history and notification history)
echo -e "\n\e[34m[6/7] Initializing clean state (clearing history/notifications)...\e[0m"
echo "[]" > "$ND_DIR/charging-history.json"
echo "[]" > "$ND_DIR/rfid-notifications.json"
echo "{}" > "$ND_DIR/last-ui-states.json"

# 9. Configure Mosquitto (Ensure Port 1883 allows external devices in Mosquitto v2+)
echo -e "\n\e[34m[7/7] Checking Mosquitto configurations...\e[0m"
if [ -f /etc/mosquitto/mosquitto.conf ]; then
    if ! grep -q "allow_anonymous" /etc/mosquitto/mosquitto.conf; then
        echo -e "\n# Added by Smart Parking setup\nlistener 1883\nallow_anonymous true" >> /etc/mosquitto/mosquitto.conf
        echo "Updated mosquitto.conf for external LAN clients."
    fi
fi

# Ensure all files are owned by the target user
chown -R "$TARGET_USER:$TARGET_USER" "$USER_HOME"

# Enable and start services
systemctl enable nodered &>/dev/null
systemctl enable node-red &>/dev/null
systemctl enable mosquitto &>/dev/null

systemctl restart mosquitto
systemctl start nodered &>/dev/null || systemctl start node-red &>/dev/null

echo -e "\n\e[32m==================================================\e[0m"
echo -e "\e[32mSmart Parking successfully deployed!\e[0m"
echo -e "\e[32mTarget User: $TARGET_USER\e[0m"
echo -e "\e[32mNode-RED UI URL: http://localhost:1880/ui\e[0m"
echo -e "\e[32mNode-RED Admin: Username '$NR_ADMIN' with custom password\e[0m"
echo -e "\e[32m==================================================\e[0m"
